def cmp_semver(a, b):
    def parse(v):
        v = v.split('+', 1)[0]
        if '-' in v:
            core, pre = v.split('-', 1)
        else:
            core, pre = v, ''
        major, minor, patch = map(int, core.split('.'))
        pre_ids = pre.split('.') if pre else []
        return major, minor, patch, pre_ids

    amaj, amin, apat, apre = parse(a)
    bmaj, bmin, bpat, bpre = parse(b)

    if (amaj, amin, apat) != (bmaj, bmin, bpat):
        return (amaj > bmaj) - (amaj < bmaj) or \
               (amin > bmin) - (amin < bmin) or \
               (apat > bpat) - (apat < bpat)

    # core equal
    if not apre and not bpre:
        return 0
    if not apre:
        return 1
    if not bpre:
        return -1

    def id_cmp(x, y):
        xn = x.isdigit()
        yn = y.isdigit()
        if xn and yn:
            xi, yi = int(x), int(y)
            return (xi > yi) - (xi < yi)
        if xn != yn:
            return -1 if xn else 1
        return (x > y) - (x < y)

    for x, y in zip(apre, bpre):
        c = id_cmp(x, y)
        if c != 0:
            return c
    return (len(apre) > len(bpre)) - (len(apre) < len(bpre))
```

