import re

def gitignore_match(pattern, path):
    pattern_dir = pattern.endswith('/')
    pattern_core = pattern.rstrip('/') if pattern_dir else pattern

    path_is_dir = path.endswith('/')
    path_core = path.rstrip('/')

    if pattern_dir and not path_is_dir:
        return False

    anchored = False
    if pattern.startswith('/'):
        anchored = True
        if pattern_core.startswith('/'):
            pattern_core = pattern_core[1:]
    elif '/' in pattern_core:
        anchored = True

    regex_body = ''
    i = 0
    n = len(pattern_core)
    while i < n:
        if pattern_core[i:i+3] == '**/':
            regex_body += '(?:[^/]+/)*'
            i += 3
            continue
        if pattern_core[i:i+3] == '/**':
            regex_body += '/.*'
            i += 3
            continue
        c = pattern_core[i]
        if c == '*':
            if i + 1 < n and pattern_core[i + 1] == '*':
                regex_body += '.*'
                i += 2
            else:
                regex_body += '[^/]*'
                i += 1
        elif c == '?':
            regex_body += '[^/]'
            i += 1
        elif c == '[':
            j = pattern_core.find(']', i + 1)
            if j == -1:
                regex_body += re.escape(c)
                i += 1
            else:
                regex_body += pattern_core[i:j + 1]
                i = j + 1
        else:
            if c in '.^$+{}()|\\':
                regex_body += '\\' + c
            else:
                regex_body += c
            i += 1

    if anchored:
        full = '^' + regex_body + '$'
    else:
        full = '^(?:.*/)?' + regex_body + '$'

    return re.match(full, path_core) is not None
