def parse_range(header, size):
    if not isinstance(header, str) or size <= 0:
        return None
    header = header.strip()
    if '=' in header:
        unit, spec = header.split('=', 1)
        if unit.strip().lower() != 'bytes':
            return None
    else:
        spec = header
    spec = spec.strip()
    if not spec:
        return None

    ranges = []
    for part in spec.split(','):
        part = part.strip()
        if not part or '-' not in part:
            return None
        left, right = part.split('-', 1)
        left = left.strip()
        right = right.strip()
        try:
            if left == '':
                suffix_len = int(right)
                if suffix_len < 0:
                    return None
                start = size - suffix_len
                if start < 0:
                    start = 0
                end = size - 1
            else:
                start = int(left)
                if start < 0:
                    start = 0
                if right == '':
                    end = size - 1
                else:
                    end = int(right)
                if end >= size:
                    end = size - 1
                if start > end:
                    continue
            if start >= size:
                continue
            if end < 0:
                continue
            ranges.append((start, end))
        except ValueError:
            return None

    return ranges if ranges else None
