import re

def unified_diff(a, b, context=3):
    if a == b:
        return []
    lines = list(difflib.unified_diff(a, b, n=context, lineterm=''))
    if len(lines) >= 2 and lines[0].startswith('---') and lines[1].startswith('+++'):
        lines = lines[2:]
    header_re = re.compile(r'@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@')
    out = []
    for line in lines:
        if line.startswith('@@'):
            m = header_re.match(line)
            if m:
                a_start = m.group(1)
                a_len = m.group(2) or '1'
                b_start = m.group(3)
                b_len = m.group(4) or '1'
                out.append(f'@@ -{a_start},{a_len} +{b_start},{b_len} @@')
            else:
                out.append(line)
        else:
            out.append(line)
    return out
