from collections import OrderedDict

class LFUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.minfreq = 0
        self.key_to_val = {}
        self.key_to_freq = {}
        self.freq_to_keys = {}

    def _update(self, key):
        freq = self.key_to_freq[key]
        od_old = self.freq_to_keys[freq]
        del od_old[key]
        if not od_old:
            del self.freq_to_keys[freq]
            if self.minfreq == freq:
                self.minfreq += 1
        new_freq = freq + 1
        self.key_to_freq[key] = new_freq
        if new_freq not in self.freq_to_keys:
            self.freq_to_keys[new_freq] = OrderedDict()
        self.freq_to_keys[new_freq][key] = None

    def get(self, key):
        if self.capacity == 0 or key not in self.key_to_val:
            return -1
        self._update(key)
        return self.key_to_val[key]

    def put(self, key, value):
        if self.capacity == 0:
            return
        if key in self.key_to_val:
            self.key_to_val[key] = value
            self._update(key)
            return
        if len(self.key_to_val) >= self.capacity:
            od_min = self.freq_to_keys[self.minfreq]
            evict_key, _ = od_min.popitem(last=False)
            del self.key_to_val[evict_key]
            del self.key_to_freq[evict_key]
            if not od_min:
                del self.freq_to_keys[self.minfreq]
        self.key_to_val[key] = value
        self.key_to_freq[key] = 1
        if 1 not in self.freq_to_keys:
            self.freq_to_keys[1] = OrderedDict()
        self.freq_to_keys[1][key] = None
        self.minfreq = 1

