def topk(stream, k):
    import heapq
    if k <= 0:
        return []
    heap = []
    for arrival, (value, label) in enumerate(stream):
        entry = (value, -arrival, label)
        if len(heap) < k:
            heapq.heappush(heap, entry)
        else:
            root_val, root_neg_arr, _ = heap[0]
            if value > root_val or (value == root_val and -arrival > root_neg_arr):
                heapq.heapreplace(heap, entry)
    # restore arrival and sort descending by value, ascending by arrival
    items = [(v, -neg_arr, lab) for v, neg_arr, lab in heap]
    items.sort(key=lambda x: (-x[0], x[1]))
    return [(v, lab) for v, arr, lab in items]
