import numba

@numba.njit
def _window_medians(arr, k):
    n = arr.shape[0]
    if k > n:
        return np.empty(0, dtype=np.float64)
    window = np.empty(k, dtype=arr.dtype)
    for i in range(k):
        window[i] = arr[i]
    for i in range(1, k):
        key = window[i]
        j = i - 1
        while j >= 0 and window[j] > key:
            window[j + 1] = window[j]
            j -= 1
        window[j + 1] = key

    out_len = n - k + 1
    out = np.empty(out_len, dtype=np.float64)
    if k & 1:
        out[0] = float(window[k // 2])
    else:
        out[0] = (float(window[k // 2 - 1]) + float(window[k // 2])) * 0.5

    for start in range(1, out_len):
        out_val = arr[start - 1]
        in_val = arr[start + k - 1]

        idx = 0
        while idx < k and window[idx] != out_val:
            idx += 1
        for j in range(idx, k - 1):
            window[j] = window[j + 1]

        j = k - 2
