    __slots__ = ('children', 'is_end')
    def __init__(self):
        self.children = {}
        self.is_end = False

class WildcardTrie:
    def __init__(self):
        self.word_counts = {}
        self.tries = {}

    def add(self, word):
        cnt = self.word_counts.get(word, 0)
        if cnt > 0:
            self.word_counts[word] = cnt + 1
            return
        self.word_counts[word] = 1
        length = len(word)
        root = self.tries.get(length)
        if root is None:
            root = Node()
            self.tries[length] = root
        node = root
        for ch in word:
            node = node.children.setdefault(ch, Node())
        node.is_end = True

    def remove(self, word):
        cnt = self.word_counts.get(word, 0)
        if cnt == 0:
            return False
        if cnt > 1:
            self.word_counts[word] = cnt - 1
            return True
        del self.word_counts[word]
        length = len(word)
        root = self.tries.get(length)
        if not root:
            return True
        path = [root]
        node = root
        for ch in word:
            nxt = node.children.get(ch)
            if nxt is None:
                return True
            node = nxt
            path.append(node)
        node.is_end = False
        for i in range(len(word), 0, -1):
            parent = path[i - 1]
            child = path[i]
            ch = word[i - 1]
            if not child.children and not child.is_end:
                del parent.children[ch]
            else:
                break
        if not root.children:
            del self.tries[length]
        return True

    def search(self, pattern):
        length = len(pattern)
        root = self.tries.get(length)
        if not root:
            return []
        results = []
        stack = [(root, 0, '')]
        while stack:
            node, idx, pref = stack.pop()
            if idx == length:
                if node.is_end:
                    results.append(pref)
                continue
            ch_pat = pattern[idx]
            if ch_pat != '.':
                child = node.children.get(ch_pat)
                if child:
                    stack.append((child, idx + 1, pref + ch_pat))
            else:
                for c, child in node.children.items():
                    stack.append((child, idx + 1, pref + c))
        results.sort()
        return results
