        if not intervals:
            return []
        iv = []
        for a in intervals:
            s, e = a[0], a[1]
            if s >= e:
                continue
            iv.append([s, e])
        if not iv:
            return []
        iv.sort(key=lambda x: x[0])
        merged = []
        cs, ce = iv[0]
        for s, e in iv[1:]:
            if s <= ce:
                if e > ce:
                    ce = e
            else:
                merged.append([cs, ce])
                cs, ce = s, e
        merged.append([cs, ce])
        return merged

    base_m = merge(base)
    cuts_m = merge(cuts)
    res = []
    j = 0
    n = len(cuts_m)
    for bs, be in base_m:
        cur = bs
        while j < n and cuts_m[j][1] <= cur:
            j += 1
        k = j
        while k < n and cuts_m[k][0] < be:
            cs, ce = cuts_m[k]
            if cs > cur:
                res.append([cur, min(cs, be)])
            cur = max(cur, ce)
            if cur >= be:
                break
            k += 1
        if cur < be:
