def deep_copy(obj):
    memo = {}

    def _copy(o):
        oid = id(o)
        if oid in memo:
            return memo[oid]
        if o is None or type(o) in (str, int, float, bool):
            return o
        if isinstance(o, dict):
            new = {}
            memo[oid] = new
            for k, v in o.items():
                new[_copy(k)] = _copy(v)
            return new
        if isinstance(o, list):
            new = []
            memo[oid] = new
            for item in o:
                new.append(_copy(item))
            return new
        if isinstance(o, set):
            new = set()
            memo[oid] = new
            for item in o:
                new.add(_copy(item))
            return new
        if isinstance(o, tuple):
            items = [_copy(item) for item in o]
            new = tuple(items)
            memo[oid] = new
            return new
        return o

    return _copy(obj)
