def to_base(n, alphabet):
    if n == 0:
        return alphabet[0]
    sign = ''
    if n < 0:
        sign = '-'
        n = -n
    base = len(alphabet)
    digits = []
    while n > 0:
        n, rem = divmod(n, base)
        digits.append(alphabet[rem])
