    if not s:
        raise ValueError('empty string')
    sign = 1
    i = 0
    if s[0] == '-':
        sign = -1
        i = 1
        if len(s) == 1:
            raise ValueError('empty string')
    base = len(alphabet)
    mapping = {c: idx for idx, c in enumerate(alphabet)}
    value = 0
    for ch in s[i:]:
        if ch not in mapping:
            raise ValueError(f'character {ch!r} not in alphabet')
        value = value * base + mapping[ch]
    return sign * value
