def shortest_path(graph, src, dst):
    if src == dst:
        return 0, [src]

    import heapq

    dist = {src: 0}
    hops = {src: 0}
    best_path = {src: [src]}

    heap = [(0, 0, (src,), src)]
    while heap:
        c, h, path, u = heapq.heappop(heap)
        if c != dist.get(u) or h != hops.get(u) or best_path.get(u) != list(path):
            continue
        if u == dst:
            return c, list(path)
