function sqlTag(strings, ...vals) {
  let text = '';
  let values = [];
  let idx = 1;

  for (let i = 0; i < strings.length; i++) {
    text += strings[i];
    if (i < vals.length) {
      const v = vals[i];
      const isSql = v && typeof v === 'object' && typeof v.text === 'string' && Array.isArray(v.values);
      if (isSql) {
        const offset = idx - 1;
        const newText = v.text.replace(/\$(\d+)/g, (_, n) => `$${offset + Number(n)}`);
        text += newText;
        values.push(...v.values);
        idx += v.values.length;
      } else if (Array.isArray(v)) {
        if (v.length === 0) {
          text += '()';
        } else {
          const placeholders = [];
          for (let j = 0; j < v.length; j++) placeholders.push(`$${idx + j}`);
          text += '(' + placeholders.join(',') + ')';
          values.push(...v);
          idx += v.length;
        }
      } else {
        text += `$${idx}`;
        values.push(v);
        idx++;
      }
    }
  }
  return { text, values };
}

