type VoidKeys<E> = { [K in keyof E]: E[K] extends void ? K : never }[keyof E];
type NonVoidKeys<E> = Exclude<keyof E, VoidKeys<E>>;

export class Bus<E extends Record<string, unknown>> {
  private listeners = new Map<keyof E, Set<(...args: any[]) => void>>();

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    let set = this.listeners.get(k);
    if (!set) {
      set = new Set();
      this.listeners.set(k, set);
    }
    set.add(fn as (...args: any[]) => void);
    return () => {
      set!.delete(fn as (...args: any[]) => void);
      if (set!.size === 0) this.listeners.delete(k);
    };
  }

  emit<K extends VoidKeys<E>>(k: K): void;
  emit<K extends NonVoidKeys<E>>(k: K, payload: E[K]): void;
  emit(k: keyof E, payload?: unknown): void {
    const set = this.listeners.get(k);
    if (!set) return;
    for (const fn of set) {
      (fn as any)(payload);
    }
  }
}
