export type Result<T, E> = { kind: 'ok'; value: T } | { kind: 'err'; error: E };

export function ok<T, E = never>(value: T): Result<T, E> {
  return { kind: 'ok', value };
}

export function err<T = never, E>(error: E): Result<T, E> {
  return { kind: 'err', error };
}

export function isOk<T, E>(r: Result<T, E>): r is { kind: 'ok'; value: T } {
  return r.kind === 'ok';
}

export function isErr<T, E>(r: Result<T, E>): r is { kind: 'err'; error: E } {
  return r.kind === 'err';
}

export function map<T, E, U>(r: Result<T, E>, fn: (v: T) => U): Result<U, E> {
  if (r.kind === 'ok') {
    return { kind: 'ok', value: fn(r.value) };
  }
  return { kind: 'err', error: r.error };
}

export function unwrapOr<T, E>(r: Result<T, E>, defaultValue: T): T {
  return r.kind === 'ok' ? r.value : defaultValue;
}

