type _FirstParam<S extends string> =
  S extends `${string}:${infer Rest}`
    ? Rest extends `${infer Name}/${infer _}` ? Name
      : Rest extends `${infer Name}` ? Name
      : never
    : never;

type _Rest<S extends string> =
  S extends `${string}:${infer Rest}`
    ? Rest extends `${infer Name}/${infer Tail}` ? `/${Tail}`
      : ''
    : S;

type ParamNames<S extends string> =
  _FirstParam<S> extends never ? never
    : _FirstParam<S> | ParamNames<_Rest<S>>;

export function defineRoutes<R extends Record<string, string>>(routes: R) {
  const out = {} as {
    [K in keyof R]: ParamNames<R[K]> extends never
      ? () => string
      : (p: { [P in ParamNames<R[K]>]: string }) => string;
  };

  for (const key of Object.keys(routes) as Array<keyof R>) {
    const tmpl = routes[key];
    (out as any)[key] = (params?: Record<string, string>) =>
      tmpl.replace(/:([A-Za-z0-9_]+)/g, (_, name) =>
        params && name in params ? encodeURIComponent(params[name]!) : `:${name}`
      );
  }

  return out;
}
