export type DeepPartial<T> =
  T extends (...args: any[]) => any ? T :
  T extends ReadonlyArray<unknown> ? T :
  T extends object ? { [K in keyof T]?: DeepPartial<T[K]> } :
  T;

export function applyPatch<T>(base: T, patch: DeepPartial<T>): T {
  if (patch === undefined) return base;
  if (typeof base !== 'object' || base === null) {
    return (patch as unknown as T) ?? base;
  }
  if (Array.isArray(patch)) return patch as unknown as T;
  if (typeof patch !== 'object' || patch === null) return patch as unknown as T;

  const result = Array.isArray(base) ? ([...base] as any) : { ...(base as any) };
  for (const key in patch) {
    if (!Object.prototype.hasOwnProperty.call(patch, key)) continue;
    const pVal = (patch as any)[key];
    if (pVal === undefined) continue;
    const bVal = (base as any)[key];
    if (Array.isArray(pVal)) {
      (result as any)[key] = pVal;
    } else if (
      typeof pVal === 'object' && pVal !== null &&
      typeof bVal === 'object' && bVal !== null && !Array.isArray(bVal)
    ) {
      (result as any)[key] = applyPatch(bVal, pVal);
    } else {
      (result as any)[key] = pVal;
    }
  }
  return result as T;
}
